// pre: dt1.length == dt2.length
public int comp(int[] dt1, int[] dt2){
  int total = dt1[0] - dt2[0];
  int index = 1;
  while( total > 0 && index < dt1.length){
    total += (dt1[index] - dt2[index]);
    index++;
  }
  return total;
}

//client code
int[] arr1 = {10, 4, 8, 3, 12};
int[] arr2 = {4, 2, 5, 16, 7};
System.out.println( comp(arr1, arr2) );

