} 

public void sort(int[] list,  
                 int st, int end){ 
  if( st >= end ) 
    return; 
  int p = (st + end) / 2; 
  swap(list, p, st); 
  int j = st; 
  for(int i = st + 1; i <= end; i++){ 
    if( list[i] <= list[st] ){ 
      j++; 
      swap(list, i, j); 
    } 
  } 

  swap(list, st, j); 
  sort(list, st, j - 1); 
  sort(list, j + 1, end); 
}

